#define SIGN_MAG(coeff, SIGN_BIT_LOC) ((coeff < 0)? ((-coeff) | (1 << SIGN_BIT_LOC)) : coeff)
#define CONVERT_2S_COMPLEMENT(coeff) ((coeff < 0)? (~(-coeff) + 1) : coeff)
#define VPP_FE_DCM_EOTF_OETF_LUT_SIZE   257
#define VPP_FE_DCM_LSH_2D_LUT_SIZE      289
