#define VPP_FE_DCM_LSH_2D_LUT_SEG_3_SIZE    256
#define VPP_FE_DCM_LSH_PACK_LSB(a,b,c)  (0xFFFFFFFF & ((c & 0x0F) << 28 | b << 14 | a));
#define VPP_FE_DCM_LSH_PACK_MSB(c)      (0x0000000F & ((c & 0xF0) >> 4));
#define VPP_FE_DCM_PACK_EOTF_OETF(a,b)  (0xFFFFFFFF & (b << 16 | a));

